package org.elharika.launcher;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.graphics.Color;import android.provider.Settings;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity {
 final ArrayList<ResolveInfo> apps=new ArrayList<>(),shown=new ArrayList<>();GridView grid;BaseAdapter adapter;String query="";boolean dark;
 @Override public void onCreate(Bundle b){dark=getPreferences(0).getBoolean("dark",false);setTheme(dark?android.R.style.Theme_Material_NoActionBar:android.R.style.Theme_Material_Light_NoActionBar);super.onCreate(b);
  LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(20,20,20,20);
  LinearLayout bar=new LinearLayout(this);Button settings=new Button(this);settings.setText(R.string.settings);settings.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_SETTINGS)));bar.addView(settings);Button theme=new Button(this);theme.setText(R.string.theme);theme.setOnClickListener(v->{getPreferences(0).edit().putBoolean("dark",!dark).apply();recreate();});bar.addView(theme);root.addView(bar);
  EditText search=new EditText(this);search.setSingleLine(true);search.setHint(R.string.search);root.addView(search);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int c){query=s.toString();filter();}public void afterTextChanged(Editable e){}});
  grid=new GridView(this);grid.setNumColumns(GridView.AUTO_FIT);grid.setColumnWidth((int)(150*getResources().getDisplayMetrics().density));grid.setStretchMode(GridView.STRETCH_COLUMN_WIDTH);
  adapter=new BaseAdapter(){public int getCount(){return shown.size();}public Object getItem(int p){return shown.get(p);}public long getItemId(int p){return p;}
   public View getView(int p,View old,android.view.ViewGroup parent){TextView v=old instanceof TextView?(TextView)old:new TextView(MainActivity.this);ResolveInfo r=shown.get(p);v.setText(r.loadLabel(getPackageManager()));v.setGravity(Gravity.CENTER);v.setPadding(10,20,10,20);v.setTextColor(dark?Color.WHITE:Color.BLACK);android.graphics.drawable.Drawable icon=r.loadIcon(getPackageManager());int size=(int)(48*getResources().getDisplayMetrics().density);icon.setBounds(0,0,size,size);v.setCompoundDrawables(null,icon,null,null);v.setMaxLines(2);return v;}};
  grid.setAdapter(adapter);grid.setOnItemClickListener((a,v,p,id)->{ResolveInfo r=shown.get(p);try{startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setComponent(new ComponentName(r.activityInfo.packageName,r.activityInfo.name)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}catch(Exception e){Toast.makeText(this,R.string.error,Toast.LENGTH_SHORT).show();}});
  grid.setOnItemLongClickListener((a,v,p,id)->{startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+shown.get(p).activityInfo.packageName)));return true;});root.addView(grid,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
 }
 void filter(){shown.clear();for(ResolveInfo r:apps)if(r.loadLabel(getPackageManager()).toString().toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))shown.add(r);if(adapter!=null)adapter.notifyDataSetChanged();}
 @Override public void onResume(){super.onResume();apps.clear();apps.addAll(getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0));apps.sort(new ResolveInfo.DisplayNameComparator(getPackageManager()));filter();}
}
